//! Small public production boundary plus exact pure frame-kernel controls.
//! Kernel inclusion is not a frontend/driver activation claim or a fake model.
#[path="../../../shared/test_scratch.rs"]mod test_scratch;
#[path="../src/daemon/retained_rejection.rs"]mod actual_frame_kernel;
pub use dmbc::request_failure;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest},request::{BuildRequest,BuildOutcome,Command},runner_host::BuildHost};
use std::{path::Path,io::{self,Write}};
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("real native PrepareQuery request")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(root.join("cache"));request.timeout_seconds=Some(60);request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalChecker0290),..Default::default()});request}
fn actual_error(root:&Path)->(BuildHost,BuildRequest,Box<dyn std::error::Error>){std::fs::write(root.join("deepquarry.dme"),include_bytes!("../../../fixtures/unified_checks/fatal_parameter_outcome_exact_bad_parameter/project.dme")).unwrap();let request=request(root);let mut host=BuildHost::default();let error=dmbc::request_runner::run_build_with_host(request.clone(),&mut host).unwrap_err();(host,request,error)}
fn decoded(bytes:&[u8])->request_failure::RequestFailure{assert!(bytes.len()>=4);let count=u32::from_le_bytes(bytes[..4].try_into().unwrap())as usize;assert_eq!(count,bytes.len()-4);let value:serde_json::Value=serde_json::from_slice(&bytes[4..]).unwrap();serde_json::from_value(value.get("Rejected").expect("same actual wire variant").clone()).unwrap()}
#[test]fn public_actual_native_fatal_keeps_funded_owner_exact_rejected_wire_and_fresh_recovery(){let root=test_scratch::dir("public-retained-native-rejection");let(mut host,request,error)=actual_error(&root);let expected=request_failure::RequestFailure::from_error(error.as_ref());assert_eq!(expected.kind,request_failure::FailureKind::Source);assert_eq!(request_failure::exit_code(error.as_ref()),2);assert!(expected.message.contains("got ')', expected one of: operator, literal, variable, proc call"));let mut current=Vec::new();assert!(dmbc::daemon::write_retained_preparation_rejection(&mut current,error.as_ref()).unwrap());let mut old=Vec::new();actual_frame_kernel::send_frame(&mut old,&serde_json::json!({"Rejected":&expected})).unwrap();assert_eq!(current,old);assert_eq!(decoded(&current),expected);assert!(!expected.message.contains("native unsupported"));drop(error);std::fs::write(root.join("deepquarry.dme"),b"/datum/valid\n    var/value = 1\n").unwrap();assert!(matches!(dmbc::request_runner::run_build_with_host(request,&mut host).unwrap(),BuildOutcome::QueryPrepared{retained:true,..}));}
#[test]fn public_actual_retained_fatal_preserves_real_writer_os_error_and_cancel_exit(){let root=test_scratch::dir("public-retained-rejection-io");let(_,_,error)=actual_error(&root);struct Fault{writes:usize,cancel:bool}impl Write for Fault{fn write(&mut self,bytes:&[u8])->io::Result<usize>{self.writes+=1;if self.writes==1{Ok(bytes.len())}else if self.cancel{Err(io::Error::new(io::ErrorKind::Interrupted,"actual cancellation"))}else{Err(io::Error::from_raw_os_error(1450))}}fn flush(&mut self)->io::Result<()>{Ok(())}}for cancel in[false,true]{let mut output=Fault{writes:0,cancel};let actual=dmbc::daemon::write_retained_preparation_rejection(&mut output,error.as_ref()).unwrap_err();assert_eq!(output.writes,2);if cancel{assert_eq!(actual.kind(),io::ErrorKind::Interrupted);assert_eq!(request_failure::exit_code(&actual),75)}else{assert_eq!(actual.raw_os_error(),Some(1450));}}}
#[test]fn ordinary_typed_errors_cannot_obtain_retained_native_rejection_transport(){let ordinary=request_failure::RequestFailure::source("ordinary caller-owned source error");let mut bytes=Vec::new();assert!(!dmbc::daemon::write_retained_preparation_rejection(&mut bytes,&ordinary).unwrap());assert!(bytes.is_empty());assert_eq!(request_failure::classify(&ordinary),request_failure::FailureKind::Source);}
#[test]fn exact_pure_frame_kernel_matches_old_wire_for_unicode_escapes_and_all_statuses(){for kind in[request_failure::FailureKind::Source,request_failure::FailureKind::Infrastructure,request_failure::FailureKind::Cancelled]{for text in["ascii","Greek \u{03b1} quote \" newline \n zero \0"]{let mut old=Vec::new();actual_frame_kernel::send_frame(&mut old,&serde_json::json!({"Rejected":request_failure::RequestFailure{kind,message:text.into()}})).unwrap();let mut current=Vec::new();actual_frame_kernel::send_rejected_text(&mut current,kind,text).unwrap();assert_eq!(current,old);let actual=decoded(&current);assert_eq!(actual.kind,kind);assert_eq!(actual.message,text);}}}
#[test]fn exact_pure_frame_kernel_refuses_oversize_before_any_stream_write(){struct Untouched;impl Write for Untouched{fn write(&mut self,_:&[u8])->io::Result<usize>{panic!("no prefix or payload before whole-frame validation")}fn flush(&mut self)->io::Result<()>{panic!("no flush")}}let text="x".repeat(actual_frame_kernel::MAX_FRAME);let error=actual_frame_kernel::send_rejected_text(&mut Untouched,request_failure::FailureKind::Source,&text).unwrap_err();assert_eq!(error.kind(),io::ErrorKind::InvalidData);}
